function renderText(text, spansObj) {
  // spansObj: {cat: [[s,e],...]}
  // collect all boundaries
  const points = new Set([0, text.length]);
  for (cat in spansObj) {
    if (!spansObj[cat].is_impossible) {
      for ([s,e] of spansObj[cat].spans) {
        points.add(s); points.add(e);
      }
    }
  }
  const sorted = Array.from(points).sort((a,b)=>a-b);
  let html = '';
  for (let i=0; i<sorted.length-1; i++) {
    const s = sorted[i];
    const e = sorted[i+1];
    const segment = text.slice(s, e);
    // find categories covering [s, s+epsilon) i.e., s >= span[0] and s < span[1]
    const cats = [];
    for (cat in spansObj) {
      if (!spansObj[cat].is_impossible) {
        for ([start,end] of spansObj[cat].spans) {
          if (start <= s && end > s) {
            cats.push(cat);
            break;
          }
        }
      }
    }
    // unique cats
    const uniqueCats = [...new Set(cats)];
    if (uniqueCats.length === 0) {
      html += escapeHtml(segment);
    } else {
      const colors = uniqueCats.map(cat => COLOR_MAP[cat]);
      // background: linear-gradient or solid if 1
      let style = '';
      if (uniqueCats.length === 1) {
        style = `background-color: ${colors[0]};`;
      } else {
        // striped gradient
        const stops = colors.map((c,i) => `${c} ${(i/uniqueCats.length)*100}%, ${c} ${((i+1)/uniqueCats.length)*100}%`);
        style = `background: linear-gradient(90deg, ${stops.join(', ')});`;
      }
      const title = uniqueCats.join(', ');
      html += `<span class="highlight" style="${style}" title="${escapeHtml(title)}">${escapeHtml(segment)}</span>`;
    }
  }
  return html;
}
