    for (const [s,e] of spans[cat].spans) {{
      points.add(s);
      points.add(e);
    }}
  }}
  const sorted = Array.from(points).sort((a,b)=>a-b);
  let html = '';
  for (let i = 0; i < sorted.length - 1; i++) {{
    const s = sorted[i];
